from collections import deque
def rects(i):
    H,W=len(i),len(i[0]); seen=[[False]*W for _ in range(H)]; res=[]
    for r in range(H):
        for c in range(W):
            if i[r][c]==3 and not seen[r][c]:
                d=deque([(r,c)]); seen[r][c]=True; cells=[]
                while d:
                    a,b=d.popleft(); cells.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<H and 0<=nb<W and i[na][nb]==3 and not seen[na][nb]:
                            seen[na][nb]=True; d.append((na,nb))
                rs=[x for x,_ in cells]; cs=[y for _,y in cells]
                res.append((min(rs),min(cs),max(rs)+1,max(cs)+1,len(cells)))
    return res
